record CounterState(int count) {}
record Increment() {}                       // action as a value type
final class Store<S> {
    private S state;
    private final List<Consumer<S>> subs = new CopyOnWriteArrayList<>();
    private final BiFunction<S, Object, S> reducer;
    synchronized void dispatch(Object a) {
        state = reducer.apply(state, a);
        subs.forEach(s -> s.accept(state));
    }
    void subscribe(Consumer<S> s) { subs.add(s); }
}
